head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vRowCount = 0;
scwin.vRowPos = 0;
scwin.vSelObj;
scwin.processGp;
scwin.vIsurCd, scwin.vBndClssCd, scwin.vBndInstCd, scwin.vSaleInstId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 숨기기
        txb_EncrypChrgPw.hide();

        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Search);
        $c.bns.BnsPanelToGroupBox(pnl_Detail);

        // 버튼초기화
        scwin.initBtn();

        // 매출기관정보 데이터셋 정의
        const sbmOptions = {
            id : "sbm_dts_SaleInst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_SaleInst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_SaleInst.insertRow();

        // 목록조회
        scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_BndClssCd1_onclick
 * @description img_BndClssCd1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BndClssCd1_onclick = function() {
    try {
        scwin.showBndClss(cmb_BndClssCd1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.img_BndClssCd1_onclick" });
    }
};

/**
 * @method
 * @name img_BndInstCd1_onclick
 * @description img_BndInstCd1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BndInstCd1_onclick = function() {
    try {
        scwin.showInst(cmb_BndInstCd1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.img_BndInstCd1_onclick" });
    }
};

/**
 * @method
 * @name img_BndClssCd_onclick
 * @description img_BndClssCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BndClssCd_onclick = function() {
    try {
        scwin.showBndClss(cmb_BndClssCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.img_BndClssCd_onclick" });
    }
};

/**
 * @method
 * @name img_BndInstCd_onclick
 * @description img_BndInstCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BndInstCd_onclick = function() {
    try {
        scwin.showInst(cmb_BndInstCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.img_BndInstCd_onclick" });
    }
};

/**
 * @method
 * @name img_IsurCd_onclick
 * @description img_IsurCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsurCd_onclick = function() {
    try {
        scwin.vSelObj = cmb_IsurCd;
        fn_GetPar = scwin.getParIsurCd;
        fn_SetPar = scwin.setParIsurCd;
        $c.bns.fn_PopIsurSearch(img_IsurCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.img_IsurCd_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05000.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vRowCount = rowcount;
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        // 해당 ROW로 이동
        if (rowcount > 0) {
            $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {
            scwin.vRowPos = dts_List.getRowPosition();

            // 버튼초기화
            btn_Create.setBackgroundImage("../img/bns/btn_40_d.gif");
            btn_Create.setDisabled("disabled");
            btn_Init.setBackgroundImage("../img/bns/btn_new_n.gif");
            btn_Init.setDisabled("");
            btn_Update.setBackgroundImage("../img/bns/btn_modify_n.gif");
            btn_Update.setDisabled("");
            btn_Delete.setBackgroundImage('../img/bns/btn_delete_n.gif');
            btn_Delete.setDisabled("");
            btn_PwdInit.setDisabled("");
            btn_PwdInit.setBackgroundImage("../img/bns/btn_32.gif");

            // 수정 키값 설정
            scwin.vIsurCd = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
            scwin.vBndInstCd = dts_List.getCellData(dts_List.getRowPosition(), "BND_INST_CD");
            scwin.vBndClssCd = dts_List.getCellData(dts_List.getRowPosition(), "BND_CLSS_CD");
            scwin.vSaleInstId = dts_List.getCellData(dts_List.getRowPosition(), "SALE_INST_ID");

            // 데이터복제
            dts_SaleInst.setBroadcast(false);
            for (let i = 1; i <= dts_SaleInst.getTotalCol(); i++) {
                dts_SaleInst.setCellData(dts_SaleInst.getRowPosition(), dts_SaleInst.getColumnID(i - 1));
                // alert('aa='+i + ' ' + dts_SaleInst.ColumnID(i) + ' ' + dts_List.NameString(dts_List.RowPosition, dts_SaleInst.ColumnID(i)) );

            }
            dts_SaleInst.setBroadcast(true, true);

            // 채권분류
            scwin.setCombo(cmb_BndClssCd, dts_SaleInst.getCellData(1, "BND_CLSS_CD"), dts_SaleInst.getCellData(1, "BND_CLSS_NM"));
            // 매출기관
            scwin.setCombo(cmb_BndInstCd, dts_SaleInst.getCellData(1, "BND_INST_CD"), dts_SaleInst.getCellData(1, "INST_NM"));
            // 발행기관
            scwin.setCombo(cmb_IsurCd, dts_SaleInst.getCellData(1, "ISUR_CD"), dts_SaleInst.getCellData(1, "ISUR_NM"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name btn_Init_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Init_onclick = function() {
    try {
        // 목록 위치 설정
        dts_List.setRowPosition(0, 0);
        // 상세초기화
        dts_SaleInst.removeAll();
        dts_SaleInst.insertRow();
        // 콤보초기화
        cmb_BndClssCd.ClearData();
        cmb_BndInstCd.ClearData();
        cmb_IsurCd.ClearData();
        // 버튼초기화
        scwin.initBtn();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.btn_Init_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === SCREN_PROCS_TP_CD_02) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "신규등록"));
        }
        if (scwin.processGp === SCREN_PROCS_TP_CD_03) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        }
        if (scwin.processGp === SCREN_PROCS_TP_CD_04) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05000.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        // 상세초기화
        dts_SaleInst.removeAll();
        dts_SaleInst.insertRow();
        // 콤보초기화
        cmb_BndClssCd.ClearData();
        cmb_BndInstCd.ClearData();
        cmb_IsurCd.ClearData();
        // 버튼초기화
        scwin.initBtn();
        scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05000.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Update_onclick = async function() {
    try {
        if (scwin.vRowCount === 0) return;
        scwin.processGp = SCREN_PROCS_TP_CD_03;
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05000.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function() {
    try {
        if (scwin.vRowCount === 0) return;
        scwin.processGp = SCREN_PROCS_TP_CD_04;
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Create_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Create_onclick = async function() {
    try {
        scwin.processGp = SCREN_PROCS_TP_CD_02;
        await scwin.create();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05000.btn_Create_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDBNS05000.xml", SCREN_PROCS_TP_CD_07, '');
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_매출기관관리.xls";
        $c.data.downloadGridViewExcel(grd_List, {fileName: "매출기관관리", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_PwdInit_onclick
 * @description 「비밀번호초기화」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_PwdInit_onclick = function() {
    try {
        scwin.pwdInit();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05000.btn_PwdInit_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 매출기관을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let param = '';
    param += "&{P}V_BND_CLSS_CD=" + cmb_BndClssCd1.getValue();
    param += "&{P}V_BND_INST_CD=" + cmb_BndInstCd1.getValue();
    let dsNm = 'BNS_PACK_SALE_INST';
    let qryId = 'lds.stf.bnspack.select.listSaleInst';
    $c.bns.fn_SearchBns("ULDBNS05000.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name update
 * @description 매출기관을 수정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (!await scwin.checkData()) return;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수정"))) return;
    let url = "/bns/SaleInstMgt.do?method=update";
    url += "&SCREN_ID=" + "ULDBNS05000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let param = "ORG_ISUR_CD=" + scwin.vIsurCd;
    param += ", ORG_BND_INST_CD=" + scwin.vBndInstCd;
    param += ", ORG_BND_CLSS_CD=" + scwin.vBndClssCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name pwdInit
 * @description 비밀번호 초기화 처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.pwdInit = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "비밀번호 초기화") + "\n\n비밀번호는 아이디와 동일하게 초기화됩니다.")) return;
    let url = "/bns/SaleInstMgt.do?method=processPwdInit";
    url += "&SCREN_ID=" + "ULDBNS05000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let param = "";
    dts_SaleInst.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name delete
 * @description 매출기관을 삭제한다.
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "삭제"))) return;
    let url = "/bns/SaleInstMgt.do?method=delete";
    url += "&SCREN_ID=" + "ULDBNS05000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let param = "ISUR_CD=" + scwin.vIsurCd;
    param += ", BND_INST_CD=" + scwin.vBndInstCd;
    param += ", BND_CLSS_CD=" + scwin.vBndClssCd;
    param += ", SALE_INST_ID=" + scwin.vSaleInstId;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name create
 * @description 매출기관을 생성한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.create = async function() {
    if (!await scwin.checkData()) return;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "신규등록"))) return;
    let url = "/bns/SaleInstMgt.do?method=createNew";
    url += "&SCREN_ID=" + "ULDBNS05000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    // trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name checkData
 * @description 입력데이터를 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function() {
    if (cmb_BndClssCd.getValue() === '') {
        await $c.win.alert("채권분류를 선택하셔야 합니다.");
        return false;
    }
    if (cmb_IsurCd.getValue() === '') {
        await $c.win.alert("발행기관을 선택하셔야 합니다.");
        return false;
    }
    if (cmb_BndInstCd.getValue() === '') {
        await $c.win.alert("매출기관을 선택하셔야 합니다.");
        return false;
    }
    if (txb_BrnNm.getValue() === '') {
        await $c.win.alert("지점명을 입력해 주세요.");
        return false;
    }
    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_BrnNm, 80, '매출기관 지점명')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자명')) return false;

    // 등록이면
    if (scwin.processGp === SCREN_PROCS_TP_CD_02) {
        // 중복체크
        let param = '';
        param += "&{P}V_BND_CLSS_CD=" + cmb_BndClssCd.getValue();
        param += "&{P}V_ISUR_CD=" + cmb_IsurCd.getValue();
        param += "&{P}V_BND_INST_CD=" + cmb_BndInstCd.getValue();
        let dsNm = 'BNS_PACK_SALE_INST_CHK';
        let qryId = 'lds.stf.bnspack.select.listSaleInstCheck';
        $c.bns.fn_SearchBns("ULDBNS05000.xml", dts_Checker, dsNm, qryId, param);
        if (dts_Checker.getRowCount() > 0) {
            await $c.win.alert('이미 등록된 코드가 있습니다.');
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name getParInst
 * @description 기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: scwin.vSelObj.getValue(),
        INST_NM: scwin.vSelObj.getValue(),
        LBL_NM: '',
        INIT_TP_CD: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParInst
 * @description 기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParInst = function(arrPar) {
    let cbdata = "^ ," + arrPar[0].INST_CD + "^" + arrPar[0].INST_NM;
    scwin.vSelObj.CBData = cbdata;
    scwin.vSelObj.setValue(arrPar[0].INST_CD);
};

/**
 * @method
 * @name getParBndClss
 * @description 채권분류 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParBndClss = function(arrPar) {
    arrPar[0] = {
        BND_CLSS_CD: '',
        BND_TP_NM: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParBndClss
 * @description 채권분류 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParBndClss = function(arrPar) {
    let cbdata = "^ ," + arrPar[0].BND_CLSS_CD + "^" + arrPar[0].BND_TP_NM;
    scwin.vSelObj.CBData = cbdata;
    scwin.vSelObj.setValue(arrPar[0].BND_CLSS_CD);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
