 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: cmb_IsurCd.getValue(),
        ISUR_NM: cmb_IsurCd.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    let cbdata = "^ ," + arrPar[0].ISUR_CD + "^" + arrPar[0].ISUR_NM;
    scwin.vSelObj.CBData = cbdata;
    scwin.vSelObj.setValue(arrPar[0].ISUR_CD);
};

/**
 * @method
 * @name showBndClss
 * @description 채권분류 팝업을 보여준다.
 * @param {*} selObj selObj
 * @returns {void}
 * @hidden N
 */
scwin.showBndClss = function(selObj) {
    scwin.vSelObj = selObj;
    fn_GetPar = scwin.getParBndClss;
    fn_SetPar = scwin.setParBndClss;
    $c.bns.fn_PopBndClssCdSearch(selObj);
};

/**
 * @method
 * @name showInst
 * @description 기관 팝업을 보여준다.
 * @param {*} selObj selObj
 * @returns {void}
 * @hidden N
 */
scwin.showInst = function(selObj) {
    scwin.vSelObj = selObj;
    fn_GetPar = scwin.getParInst;
    fn_SetPar = scwin.setParInst;
    $c.bns.fn_PopInstSearch(selObj);
};

/**
 * @method
 * @name setCombo
 * @description 콤보데이터를 설정한다.
 * @param {*} selObj selObj
 * @param {*} cd cd
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function(selObj, cd, val) {
    scwin.vSelObj = selObj;
    let cbdata = "^ ," + cd + "^" + val;
    scwin.vSelObj.CBData = cbdata;
    scwin.vSelObj.setValue(cd);
};

/**
 * @method
 * @name initBtn
 * @description 버튼을 초기화 한다.
 * @returns {void}
 * @hidden N
 */
scwin.initBtn = function() {
    btn_Create.setBackgroundImage("../img/bns/btn_40.gif");
    btn_Create.setDisabled("");
    btn_Init.setBackgroundImage("../img/bns/btn_new_nd.gif");
    btn_Init.setDisabled("disabled");
    btn_Update.setDisabled("disabled");
    btn_Update.setBackgroundImage("../img/bns/btn_modify_nd.gif");
    btn_Delete.setDisabled("disabled");
    btn_Delete.setBackgroundImage("../img/bns/btn_delete_nd.gif");
    btn_PwdInit.setDisabled("disabled");
    btn_PwdInit.setBackgroundImage("../img/bns/btn_32_d.gif");
};
